create extension if not exists pgcrypto;
drop table if exists road_reports cascade; drop table if exists rider_events cascade; drop table if exists trips cascade; drop table if exists road_events cascade; drop table if exists riders cascade;
create table riders(id text primary key,name text not null,vouch_score int not null default 74,score_factors jsonb not null default '[]',total_distance numeric not null default 0,created_at timestamptz not null default now());
create table trips(id text primary key,rider_id text not null references riders(id) on delete cascade,start_time timestamptz,end_time timestamptz,distance numeric not null default 0,score_change int not null default 0,created_at timestamptz not null default now());
create table road_events(id text primary key,type text not null,latitude double precision not null,longitude double precision not null,confidence numeric not null default .5,status text not null default 'possible',reports int not null default 1,riders int not null default 1,first_detected text,last_confirmed text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table rider_events(id text primary key,trip_id text not null references trips(id) on delete cascade,rider_id text not null references riders(id) on delete cascade,event_type text not null,latitude double precision not null,longitude double precision not null,motion_data jsonb,context_result jsonb,confidence numeric not null default 0,created_at timestamptz not null default now());
create table road_reports(id uuid primary key default gen_random_uuid(),road_event_id text references road_events(id) on delete cascade,rider_id text not null references riders(id) on delete cascade,created_at timestamptz not null default now());
create unique index road_reports_event_rider_unique on road_reports(road_event_id,rider_id);
